            <XAxis
              type="number"
              dataKey="MD"
              name="MD"
              tick={{ fill: '#fff', fontSize: 'clamp(8px, 2.5vw, 12px)' }}
              label={{
                value: 'MD',
                position: 'bottom',
                offset: 10,
                fill: '#fff',
                style: { fontSize: 'clamp(10px, 3vw, 14px)' }
              }}
            />
            
            <YAxis
              type="number"
              dataKey="YTM"
